import { api } from './authService';

const roomService = {
  /** GET /rooms */
  getAll: async (params = {}) => {
    const { data } = await api.get('/rooms', { params });
    return data?.data ?? data;
  },

  getAvailable: async ({ checkIn, checkOut } = {}) => {
    const { data } = await api.get('/rooms/available', {
      params: { checkIn, checkOut },
    });
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/rooms/${id}`);
    return data?.data ?? data;
  },

  /** POST /rooms
   * ✅ FIX : mapping des champs frontend → backend
   *   price_per_night → price
   *   type "double"   → "DOUBLE" (enum Java)
   */
  create: async (roomData) => {
    const payload = {
      number:      roomData.number,
      type:        roomData.type?.toUpperCase(),
      price:       roomData.price_per_night,
      capacity:    Number(roomData.capacity) || 1,
      description: roomData.description || '',
    };
    const { data } = await api.post('/rooms', payload);
    return data?.data ?? data;
  },

  /** PUT /rooms/{id} */
  update: async (id, roomData) => {
    const payload = {
      number:      roomData.number,
      type:        roomData.type?.toUpperCase(),
      price:       roomData.price_per_night,
      capacity:    Number(roomData.capacity) || 1,
      description: roomData.description || '',
    };
    const { data } = await api.put(`/rooms/${id}`, payload);
    return data?.data ?? data;
  },

  delete: async (id) => {
    const { data } = await api.delete(`/rooms/${id}`);
    return data?.data ?? data;
  },
};

export default roomService;
